package com.google.gson.stream;

import java.io.*;
import java.io.Closeable;
import java.io.Flushable;
import java.io.IOException;
import java.io.StringWriter;
import java.io.Writer;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

public class JsonWriter_value_TriageGen1Test {

    private JsonWriter writer;

    @Before
    public void setUp() throws IOException {
        writer = new JsonWriter(new StringWriter());
    }

    @Test(expected = IllegalArgumentException.class)
    public void testValueWithNaN() throws IOException {
        writer.value(Double.NaN);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testValueWithPositiveInfinity() throws IOException {
        writer.value(Double.POSITIVE_INFINITY);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testValueWithNegativeInfinity() throws IOException {
        writer.value(Double.NEGATIVE_INFINITY);
    }

    @Test
    public void testValueWithFiniteNumber() throws IOException {
        writer.beginObject()
              .name("test")
              .value(123.45)
              .endObject();
        String expected = "{\"test\":123.45}";
        assertEquals(expected, writer.getPayload().toString());
    }

    @Test
    public void testValueWithZero() throws IOException {
        writer.beginObject()
              .name("test")
              .value(0.0)
              .endObject();
        String expected = "{\"test\":0.0}";
        assertEquals(expected, writer.getPayload().toString());
    }

    @Test
    public void testValueWithNegativeNumber() throws IOException {
        writer.beginObject()
              .name("test")
              .value(-123.45)
              .endObject();
        String expected = "{\"test\":-123.45}";
        assertEquals(expected, writer.getPayload().toString());
    }

    @Test
    public void testValueWithLargeNumber() throws IOException {
        writer.beginObject()
              .name("test")
              .value(1.7976931348623157E308)
              .endObject();
        String expected = "{\"test\":1.7976931348623157E308}";
        assertEquals(expected, writer.getPayload().toString());
    }

    @Test
    public void testValueWithSmallNumber() throws IOException {
        writer.beginObject()
              .name("test")
              .value(4.9E-324)
              .endObject();
        String expected = "{\"test\":4.9E-324}";
        assertEquals(expected, writer.getPayload().toString());
    }

    @Test
    public void testValueWithDecimalNumber() throws IOException {
        writer.beginObject()
              .name("test")
              .value(123.456)
              .endObject();
        String expected = "{\"test\":123.456}";
        assertEquals(expected, writer.getPayload().toString());
    }
}
